              ['Puretex', 'označení vlastní vodě odolné konstrukce', 'ověřte, zda jde o membránu nebo jen o úpravu svršku'],
              ['Wns, Wn, Jr, Inf', 'dámské, dětské a nejmenší děti', 'velikostní řada se liší, nepřenášejte číslo mezi řadami naslepo'],
